// go-icon.js

export const GO_ICON_KEY = 'cattymod:goIcon';

export const GO_ICON_PLAY = 'play';
export const GO_ICON_GREEN_FLAG = 'greenflag';
export const GO_ICON_BLUE_FLAG = 'blueflag';
export const GO_ICON_PURPLE_FLAG = 'purpleflag';

/*
 * Play Button (ALL)
 */
export const CATTY_GREEN_FLAG =
    'https://cattymod.app/assets/green-flag.svg';

/*
 * Green Flag (EVERYTHING EXCEPT BLOCKS)
 */
export const TURBO_GREEN_FLAG =
    'https://turbowarp.org/static/blocks-media/default/green-flag.svg';

/*
 * Green Flag (BLOCKS)
 */
export const FULL_BASE64_GREEN_FLAG =
    'data:image/svg+xml;base64,';

/*
 * Blue Flag (ALL)
 */
export const BLUE_FLAG =
    'https://studio.penguinmod.com/static/blocks-media/blue-flag.svg';

/*
 * Purple Flag (EVERYTHING EXCEPT BLOCKS)
 */
export const PURPLE_FLAG =
    'data:image/svg+xml;base64,';

/*
 * Purple Flag (BLOCKS)
 *
 * Snail IDE is a PenguinMod mod. Its purple flag
 * asset is still named blue-flag.svg.
 */
export const PURPLE_FLAG_BLOCKS =
    'https://snail-ide.js.org/static/blocks-media/blue-flag.svg';

/*
 * file:// pages do not support Go Icon.
 */
const isFileProtocol = () =>
    typeof window !== 'undefined' &&
    window.location.protocol === 'file:';

/*
 * Get the currently selected icon mode.
 */
export const getGoIcon = () => {
    if (isFileProtocol()) {
        return GO_ICON_PLAY;
    }

    try {
        const stored = localStorage.getItem(GO_ICON_KEY);

        if (
            stored === GO_ICON_PLAY ||
            stored === GO_ICON_GREEN_FLAG ||
            stored === GO_ICON_BLUE_FLAG ||
            stored === GO_ICON_PURPLE_FLAG
        ) {
            return stored;
        }
    } catch (e) {
        // Ignore localStorage errors.
    }

    return GO_ICON_PLAY;
};

/*
 * Save the selected icon mode.
 */
export const setGoIcon = mode => {
    if (isFileProtocol()) {
        return;
    }

    if (
        mode !== GO_ICON_PLAY &&
        mode !== GO_ICON_GREEN_FLAG &&
        mode !== GO_ICON_BLUE_FLAG &&
        mode !== GO_ICON_PURPLE_FLAG
    ) {
        return;
    }

    try {
        localStorage.setItem(GO_ICON_KEY, mode);
    } catch (e) {
        // Ignore localStorage errors.
    }
};

/*
 * Get the replacement used by normal <img> elements.
 */
export const getGoIconImage = mode => {
    if (mode === GO_ICON_GREEN_FLAG) {
        return FULL_BASE64_GREEN_FLAG;
    }

    if (mode === GO_ICON_BLUE_FLAG) {
        return BLUE_FLAG;
    }

    if (mode === GO_ICON_PURPLE_FLAG) {
        return PURPLE_FLAG;
    }

    return CATTY_GREEN_FLAG;
};

/*
 * Get the replacement used by SVG <image> elements.
 */
export const getGoIconSvg = mode => {
    if (mode === GO_ICON_GREEN_FLAG) {
        return TURBO_GREEN_FLAG;
    }

    if (mode === GO_ICON_BLUE_FLAG) {
        return BLUE_FLAG;
    }

    if (mode === GO_ICON_PURPLE_FLAG) {
        return PURPLE_FLAG_BLOCKS;
    }

    return CATTY_GREEN_FLAG;
};

/*
 * Replace all green flag icons currently on the page.
 */
export const replaceGreenFlags = mode => {
    if (
        typeof document === 'undefined' ||
        isFileProtocol()
    ) {
        return;
    }

    if (!navigator.onLine) {
        return;
    }

    const imgReplacement = getGoIconImage(mode);
    const svgHrefReplacement = getGoIconSvg(mode);

    /*
     * Replace normal <img> green flags.
     */
    try {
        document.querySelectorAll('img').forEach(e => {
            try {
                if (
                    (
                        e.className &&
                        e.className.includes &&
                        e.className.includes('green-flag')
                    ) ||
                    (
                        e.closest &&
                        e.closest(
                            '.stage_green-flag-overlay_gNXnv'
                        )
                    )
                ) {
                    e.src = imgReplacement;
                }
            } catch (err) {
                // Ignore individual element errors.
            }
        });
    } catch (err) {
        // Ignore query errors.
    }

    /*
     * Replace SVG <image> green flags.
     */
    try {
        document.querySelectorAll('image').forEach(e => {
            try {
                const href =
                    e.getAttribute('xlink:href') ||
                    e.getAttribute('href');

                if (href && href.includes('green-flag.svg')) {
                    e.setAttribute(
                        'xlink:href',
                        svgHrefReplacement
                    );

                    e.setAttribute(
                        'href',
                        svgHrefReplacement
                    );
                }
            } catch (err) {
                // Ignore individual element errors.
            }
        });
    } catch (err) {
        // Ignore query errors.
    }
};

/*
 * Stop the current green flag observer.
 */
export const stopGoIconObserver = () => {
    try {
        if (window._cattymod_goIcon_observer) {
            window._cattymod_goIcon_observer.disconnect();
            window._cattymod_goIcon_observer = null;
        }
    } catch (e) {
        // Ignore observer errors.
    }
};

/*
 * Start watching the page for newly-created green flag icons.
 */
export const startGoIconObserver = () => {
    if (
        typeof document === 'undefined' ||
        typeof window === 'undefined' ||
        isFileProtocol()
    ) {
        return;
    }

    if (!navigator.onLine) {
        return;
    }

    stopGoIconObserver();

    const mode = getGoIcon();

    replaceGreenFlags(mode);

    try {
        const observer = new MutationObserver(() => {
            if (isFileProtocol()) {
                stopGoIconObserver();
                return;
            }

            if (!navigator.onLine) {
                stopGoIconObserver();
                return;
            }

            replaceGreenFlags(mode);
        });

        const target =
            document.body || document.documentElement;

        observer.observe(target, {
            childList: true,
            subtree: true
        });

        window._cattymod_goIcon_observer = observer;
    } catch (e) {
        // Ignore MutationObserver errors.
    }
};

/*
 * Apply a new Go Icon mode.
 */
export const applyGoIcon = mode => {
    if (isFileProtocol()) {
        return;
    }

    if (
        mode !== GO_ICON_PLAY &&
        mode !== GO_ICON_GREEN_FLAG &&
        mode !== GO_ICON_BLUE_FLAG &&
        mode !== GO_ICON_PURPLE_FLAG
    ) {
        return;
    }

    setGoIcon(mode);

    if (!navigator.onLine) {
        stopGoIconObserver();
        return;
    }

    startGoIconObserver();
};

/*
 * Re-apply the icon after fullscreen changes.
 *
 * TurboWarp can recreate parts of the UI when fullscreen
 * is entered or exited, so give it a few chances to finish.
 */
export const handleGoIconFullscreenChange = () => {
    if (isFileProtocol()) {
        return;
    }

    setTimeout(() => {
        if (!isFileProtocol() && navigator.onLine) {
            startGoIconObserver();
        }
    }, 0);

    setTimeout(() => {
        if (!isFileProtocol() && navigator.onLine) {
            startGoIconObserver();
        }
    }, 100);

    setTimeout(() => {
        if (!isFileProtocol() && navigator.onLine) {
            startGoIconObserver();
        }
    }, 500);
};

/*
 * Automatically start the observer when the document is ready.
 */
export const initializeGoIcon = () => {
    if (
        typeof document === 'undefined' ||
        isFileProtocol()
    ) {
        return () => {};
    }

    const start = () => {
        if (!isFileProtocol() && navigator.onLine) {
            startGoIconObserver();
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener(
            'DOMContentLoaded',
            start,
            {once: true}
        );
    } else {
        start();
    }

    document.addEventListener(
        'fullscreenchange',
        handleGoIconFullscreenChange
    );

    return () => {
        document.removeEventListener(
            'fullscreenchange',
            handleGoIconFullscreenChange
        );

        stopGoIconObserver();
    };
};
